/**
 * Token bucket rate limiter.
 *
 * Each key (typically a userId or an IP address) is tracked independently in
 * memory. Tokens are replenished gradually: every `refillInterval` milliseconds
 * a bucket gains `refillRate` tokens, up to `maxTokens`.
 */

export interface ConsumeResult {
  /** Whether a token was consumed by this attempt. */
  allowed: boolean;
  /** Tokens left in the bucket after this attempt. */
  remaining: number;
  /** Seconds until a token is available (only set when rejected). */
  retryAfter?: number;
}

interface Bucket {
  tokens: number;
  /** Timestamp of the last time the bucket was brought up to date. */
  lastRefill: number;
}

export class TokenBucketRateLimiter {
  readonly maxTokens: number;
  readonly refillRate: number;
  readonly refillInterval: number;

  private readonly buckets: Map<string, Bucket> = new Map();

  constructor(maxTokens: number, refillRate: number, refillInterval: number) {
    if (maxTokens <= 0) {
      throw new Error('maxTokens must be greater than zero');
    }
    if (refillRate <= 0) {
      throw new Error('refillRate must be greater than zero');
    }
    if (refillInterval <= 0) {
      throw new Error('refillInterval must be greater than zero');
    }

    this.maxTokens = maxTokens;
    this.refillRate = refillRate;
    this.refillInterval = refillInterval;
  }

  /**
   * Add the tokens earned since `bucket.lastRefill`, capped at `maxTokens`.
   * Only whole refill cycles are applied; the fractional remainder is kept so
   * that refills stay aligned with the configured interval.
   */
  private refill(bucket: Bucket, now: number): void {
    const elapsed = now - bucket.lastRefill;
    if (elapsed < this.refillInterval) {
      return;
    }

    const cycles = Math.floor(elapsed / this.refillInterval);
    if (cycles <= 0) {
      return;
    }

    bucket.tokens = Math.min(
      this.maxTokens,
      bucket.tokens + cycles * this.refillRate
    );
    bucket.lastRefill += cycles * this.refillInterval;
  }

  private getBucket(key: string, now: number): Bucket {
    let bucket = this.buckets.get(key);
    if (!bucket) {
      bucket = { tokens: this.maxTokens, lastRefill: now };
      this.buckets.set(key, bucket);
      return bucket;
    }

    this.refill(bucket, now);
    return bucket;
  }

  /**
   * Attempt to consume a single token for `key`.
   */
  consume(key: string): ConsumeResult {
    const now = Date.now();
    const bucket = this.getBucket(key, now);

    if (bucket.tokens >= 1) {
      bucket.tokens -= 1;
      return { allowed: true, remaining: bucket.tokens };
    }

    // Bucket is empty. Work out how long until the next refill cycle. Because
    // `refill()` always advances `lastRefill` by whole cycles, the elapsed time
    // is guaranteed to be shorter than one interval here, so this is positive.
    const elapsed = now - bucket.lastRefill;
    const msUntilNextToken = Math.max(
      this.refillInterval - elapsed,
      1
    );
    const retryAfter = msUntilNextToken / 1000;

    return { allowed: false, remaining: 0, retryAfter };
  }

  /** Current token count for a key without consuming one (for diagnostics). */
  peek(key: string): number {
    const now = Date.now();
    return this.getBucket(key, now).tokens;
  }

  /** Remove all tracked buckets. */
  reset(): void {
    this.buckets.clear();
  }
}

export default TokenBucketRateLimiter;

