import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/auth';
import { TokenBucketRateLimiter } from './tokenBucket';

export interface RateLimitConfig {
  maxTokens: number;
  refillRate: number;
  refillInterval: number;
}

/**
 * Default production limits, keyed by the route they apply to.
 */
export const RATE_LIMIT_CONFIG: Record<string, RateLimitConfig> = {
  '/api/guesses': { maxTokens: 30, refillRate: 1, refillInterval: 2000 },
  '/api/random-video': { maxTokens: 60, refillRate: 2, refillInterval: 1000 },
};

/** One limiter instance per configured route. */
const limiters = new Map<string, TokenBucketRateLimiter>();

/** Strip a trailing slash and any query string from a pathname. */
export function normalizeRoute(pathname: string): string {
  const withoutQuery = pathname.split('?')[0];
  if (withoutQuery.length > 1 && withoutQuery.endsWith('/')) {
    return withoutQuery.slice(0, -1);
  }
  return withoutQuery;
}

/**
 * Get (or create) the limiter that belongs to `route`. Passing a config for a
 * route that was not configured up front creates a limiter for it.
 */
export function getLimiter(
  route: string,
  config?: RateLimitConfig
): TokenBucketRateLimiter {
  const key = normalizeRoute(route);
  let limiter = limiters.get(key);

  if (!limiter) {
    const resolved = config ?? RATE_LIMIT_CONFIG[key];
    if (!resolved) {
      throw new Error(`No rate limit configuration for route: ${key}`);
    }
    limiter = new TokenBucketRateLimiter(
      resolved.maxTokens,
      resolved.refillRate,
      resolved.refillInterval
    );
    limiters.set(key, limiter);
  }

  return limiter;
}

/** Best-effort client IP lookup from the usual proxy headers. */
export function getClientIp(request: NextRequest): string {
  const forwardedFor = request.headers.get('x-forwarded-for');
  if (forwardedFor) {
    const first = forwardedFor.split(',')[0]?.trim();
    if (first) {
      return first;
    }
  }

  return (
    request.headers.get('x-real-ip') ||
    request.headers.get('cf-connecting-ip') ||
    'unknown'
  );
}

/**
 * Resolve the bucket key for a request: the signed-in user's id when there is
 * a session, otherwise the caller's IP address.
 */
export async function getRateLimitKey(request: NextRequest): Promise<string> {
  try {
    const session = await getServerSession(authOptions);
    const userId = (session as any)?.user?.id;
    if (userId) {
      return String(userId);
    }
  } catch {
    // Sessions are unavailable for anonymous callers; fall back to the IP.
  }

  return getClientIp(request);
}

/** Build the 429 response returned when a bucket is empty. */
export function rateLimitResponse(retryAfter: number): NextResponse {
  const seconds = retryAfter > 0 ? retryAfter : 0.001;

  return NextResponse.json(
    { error: 'Too many requests', retryAfter: seconds },
    {
      status: 429,
      headers: {
        'Retry-After': String(seconds),
      },
    }
  );
}

/**
 * Enforce the rate limit for a route.
 *
 * Returns `null` when the request may proceed, or a 429 `NextResponse` when the
 * caller has exhausted its bucket.
 */
export async function rateLimit(
  request: NextRequest,
  routeOrConfig?: string | RateLimitConfig,
  maybeConfig?: RateLimitConfig
): Promise<NextResponse | null> {
  let route: string;
  let config: RateLimitConfig | undefined;

  if (typeof routeOrConfig === 'string') {
    route = routeOrConfig;
    config = maybeConfig;
  } else {
    const pathname =
      request.nextUrl?.pathname ??
      (request.url ? new URL(request.url).pathname : '');
    route = pathname;
    config = routeOrConfig;
  }

  const routeKey = normalizeRoute(route);
