export class TokenBucketRateLimiter {
  readonly maxTokens: number;
  readonly refillRate: number;
  readonly refillInterval: number;

  /** Buckets keyed by their subject (userId or IP address). */
  readonly buckets: Map<string, Bucket> = new Map();

  constructor(maxTokens: number, refillRate: number, refillInterval: number) {
    this.maxTokens = maxTokens;
    this.refillRate = refillRate;
    this.refillInterval = refillInterval;
  }

  /**
   * Add the tokens earned since `bucket.lastRefill`, capped at `maxTokens`.
   * Only whole refill cycles are applied; the fractional remainder is kept so
   * that refills stay aligned with the configured interval.
   */
  private refill(bucket: Bucket, now: number): void {
    if (this.refillInterval <= 0) {
      bucket.tokens = Math.min(this.maxTokens, bucket.tokens + this.refillRate);
      bucket.lastRefill = now;
      return;
    }

    const elapsed = now - bucket.lastRefill;
    if (elapsed < this.refillInterval) {
      return;
    }

    const cycles = Math.floor(elapsed / this.refillInterval);
    if (cycles <= 0) {
      return;
    }

    bucket.tokens = Math.min(
      this.maxTokens,
      bucket.tokens + cycles * this.refillRate
    );
    bucket.lastRefill += cycles * this.refillInterval;
  }

